// Intercepts user prompt before sending to LLM
export function onUserPrompt(prompt: string) {
  if (prompt.startsWith('/audit')) {
    return {
      action: 'inject_transient_skill',
      skill: 'mayall-solidity-security',
      prompt: prompt.replace('/audit', '').trim()
    };
  }
  return null;
}
